function createAttemptWorker(attemptStore, clock) {
  return {
    async save(attempt) {
      const saved = { ...attempt, savedAt: clock.now() };
      await attemptStore.save(saved);
      return saved;
    },
  };
}

const worker = createAttemptWorker(
  { save: async (a) => console.log("db", a) },
  { now: () => Date.now() }
);

await worker.save({ id: "a-1" });

class AuthHandler {
  constructor(issuer) { this.issuer = issuer; }
  parse(raw) { throw new Error("override"); }
}

class LtiHandler extends AuthHandler {
  parse(raw) {
    return { issuer: this.issuer, kind: "lti", raw };
  }
}

function process(handler, raw) {
  return handler.parse(raw); // polymorphic — runtime type wins
}

process(new LtiHandler("school"), "jwt");

const Loggable = {
  log(msg) {
    console.log(`[${this.constructor.name}]`, msg);
  },
};

class Service {
  constructor(name) { this.name = name; }
}

Object.assign(Service.prototype, Loggable);

const s = new Service("cache");
s.log("ready"); // [Service] ready

class BaseWorker {
  constructor() {
    this.init(); // calls override before subclass ready
  }
  init() { this.ready = true; }
}

class CacheWorker extends BaseWorker {
  constructor(store) {
    super();
    this.store = store;
  }
  init() {
    this.cache = this.store.connect(); // store may be undefined!
  }
}

new CacheWorker({ connect: () => "redis" }); // throws or undefined
